var Foundation = class {
  baseField = "base-field";

  constructor(prefix) {
    console.log("base-constructor");
    this.prefix = prefix;
  }

  inherited(value) {
    return `${this.prefix}:${this.baseField}:${value}`;
  }

  render(value) {
    return `base(${value})`;
  }

  identity() {
    return this;
  }
};

export { Foundation };
